import{_ as s,a,c as o,ac as t}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第一册：英语初阶 · 综合复习与自测 · 第1–7课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第一册：英语初阶 · 综合复习与自测 · 第1–7课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-1/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第一册：英语初阶 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · 综合复习与自测","link":"/life/english/new-concept/book-1/review"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第8–15课","link":"/life/english/new-concept/book-1/review-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · 综合复习与自测","link":"/life/english/new-concept/book-1/review"},"next":{"text":"第一册：英语初阶 · 综合复习与自测 · 第8–15课","link":"/life/english/new-concept/book-1/review-part-02"}},"headers":[],"relativePath":"life/english/new-concept/book-1/review-part-01.md","filePath":"life/english/new-concept/book-1/review-part-01.md"}'),n={name:"life/english/new-concept/book-1/review-part-01.md"};function i(r,e,l,h,c,p){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="第一册-英语初阶-·-综合复习与自测-·-第1–7课" tabindex="-1">第一册：英语初阶 · 综合复习与自测 · 第1–7课 <a class="header-anchor" href="#第一册-英语初阶-·-综合复习与自测-·-第1–7课" aria-label="Permalink to &quot;第一册：英语初阶 · 综合复习与自测 · 第1–7课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-1/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="第一册-英语初阶-·-综合复习与自测" tabindex="-1">第一册：英语初阶 · 综合复习与自测 <a class="header-anchor" href="#第一册-英语初阶-·-综合复习与自测" aria-label="Permalink to &quot;第一册：英语初阶 · 综合复习与自测 {#第一册-英语初阶-·-综合复习与自测}&quot;">​</a></h2><p><a href="/life/english/new-concept/book-1/overview">本册介绍</a> · <a href="/life/english/new-concept/book-1/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-1/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-1/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-1/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-1/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-1/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-1-·-be-动词的一般疑问句" tabindex="-1">Lesson 1 · be 动词的一般疑问句 <a class="header-anchor" href="#lesson-1-·-be-动词的一般疑问句" aria-label="Permalink to &quot;Lesson 1 · be 动词的一般疑问句 {#lesson-1-·-be-动词的一般疑问句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Is this your ticket?</p><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1 {#练习-1}&quot;">​</a></h3><p>填入 be：___ this your ticket?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Is</p><p><strong>解析：</strong> 按本课规则判断：含 be 的陈述句变一般疑问句时，将 be 移到主语之前。this 指近处单数物品，回答时通常用 it。简短肯定回答必须保留 is，不能以 Yes, it&#39;s. 结尾。your 是物主限定词，后面接名词，不随物品的数量改变；礼貌开场和确认信息是两个不同的交际步骤。</p></details><p><strong>表达迁移：</strong> 围绕“礼貌确认身边物品的归属”写两至三句，再读给同伴听。至少使用一次be 动词的一般疑问句，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Is this your ticket? Is this your notebook?</p><p>Is 是前置的系动词，this 是主语，your ticket 是表语；your 限定 ticket 的归属。回答时用 it 代替 this ticket。 Is 前置形成问句，this 指近处的一件物品，your notebook 是表语。notebook 为单数，所以使用 is。</p></details><p><a href="/life/english/new-concept/book-1/unit-01/lesson-001">回看本课</a></p><h2 id="lesson-2-·-be-动词的一般疑问句" tabindex="-1">Lesson 2 · be 动词的一般疑问句 <a class="header-anchor" href="#lesson-2-·-be-动词的一般疑问句" aria-label="Permalink to &quot;Lesson 2 · be 动词的一般疑问句 {#lesson-2-·-be-动词的一般疑问句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Is this your notebook?</p><h3 id="练习-1-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-1" aria-label="Permalink to &quot;练习 1 {#练习-1-1}&quot;">​</a></h3><p>补全肯定回答：Yes, it ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> is</p><p><strong>解析：</strong> 按本课规则判断：含 be 的陈述句变一般疑问句时，将 be 移到主语之前。this 指近处单数物品，回答时通常用 it。简短肯定回答必须保留 is，不能以 Yes, it&#39;s. 结尾。your 是物主限定词，后面接名词，不随物品的数量改变；礼貌开场和确认信息是两个不同的交际步骤。</p></details><p><strong>表达迁移：</strong> 围绕“礼貌确认身边物品的归属”写两至三句，再读给同伴听。至少使用一次be 动词的一般疑问句，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Is this your notebook? Is this your ticket?</p><p>Is 前置形成问句，this 指近处的一件物品，your notebook 是表语。notebook 为单数，所以使用 is。 Is 是前置的系动词，this 是主语，your ticket 是表语；your 限定 ticket 的归属。回答时用 it 代替 this ticket。</p></details><p><a href="/life/english/new-concept/book-1/unit-01/lesson-002">回看本课</a></p><h2 id="lesson-3-·-be-动词的否定和缩写" tabindex="-1">Lesson 3 · be 动词的否定和缩写 <a class="header-anchor" href="#lesson-3-·-be-动词的否定和缩写" aria-label="Permalink to &quot;Lesson 3 · be 动词的否定和缩写 {#lesson-3-·-be-动词的否定和缩写}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> This is not my umbrella.</p><h3 id="练习-1-2" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-2" aria-label="Permalink to &quot;练习 1 {#练习-1-2}&quot;">​</a></h3><p>补全否定句：This ___ not my umbrella.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> is</p><p><strong>解析：</strong> 按本课规则判断：否定句在 be 后加 not。is not 可缩为 isn&#39;t；this is 的主语指单数物品。否定回答应先表明不是，再补充正确归属。my、your 后必须接名词；不能把否定词放在名词前来替代谓语否定。sorry 用于表达歉意，excuse me 多用于打扰前引起注意，语境不同。</p></details><p><strong>表达迁移：</strong> 围绕“发现认错物品后否认并道歉”写两至三句，再读给同伴听。至少使用一次be 动词的否定和缩写，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>This is not my umbrella. That is not your coat.</p><p>This 是主语，is 是系动词，not 否定整项归属，my umbrella 是表语；my 后保留名词 umbrella。 That 指稍远的单数物品；is not 是系表结构的否定，your coat 说明被否定的所属关系。</p></details><p><a href="/life/english/new-concept/book-1/unit-01/lesson-003">回看本课</a></p><h2 id="lesson-4-·-be-动词的否定和缩写" tabindex="-1">Lesson 4 · be 动词的否定和缩写 <a class="header-anchor" href="#lesson-4-·-be-动词的否定和缩写" aria-label="Permalink to &quot;Lesson 4 · be 动词的否定和缩写 {#lesson-4-·-be-动词的否定和缩写}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> That is not your coat.</p><h3 id="练习-1-3" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-3" aria-label="Permalink to &quot;练习 1 {#练习-1-3}&quot;">​</a></h3><p>将 is not 写成缩写。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> isn&#39;t</p><p><strong>解析：</strong> 按本课规则判断：否定句在 be 后加 not。is not 可缩为 isn&#39;t；this is 的主语指单数物品。否定回答应先表明不是，再补充正确归属。my、your 后必须接名词；不能把否定词放在名词前来替代谓语否定。sorry 用于表达歉意，excuse me 多用于打扰前引起注意，语境不同。</p></details><p><strong>表达迁移：</strong> 围绕“发现认错物品后否认并道歉”写两至三句，再读给同伴听。至少使用一次be 动词的否定和缩写，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>That is not your coat. This is not my umbrella.</p><p>That 指稍远的单数物品；is not 是系表结构的否定，your coat 说明被否定的所属关系。 This 是主语，is 是系动词，not 否定整项归属，my umbrella 是表语；my 后保留名词 umbrella。</p></details><p><a href="/life/english/new-concept/book-1/unit-01/lesson-004">回看本课</a></p><h2 id="lesson-5-·-身份介绍与特殊疑问句" tabindex="-1">Lesson 5 · 身份介绍与特殊疑问句 <a class="header-anchor" href="#lesson-5-·-身份介绍与特殊疑问句" aria-label="Permalink to &quot;Lesson 5 · 身份介绍与特殊疑问句 {#lesson-5-·-身份介绍与特殊疑问句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> This is Eva. She is German.</p><h3 id="练习-1-4" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-4" aria-label="Permalink to &quot;练习 1 {#练习-1-4}&quot;">​</a></h3><p>填国籍形容词：She is from Germany. She is ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> German</p><p><strong>解析：</strong> 按本课规则判断：介绍某人可以用 This is + 姓名。描述国籍通常用 be + 国籍形容词，不加 a。what make 询问品牌，make 在这里是名词；特殊疑问句常用疑问词组 + be + 主语。单数职业名词一般需要 a/an，品牌专名通常不用不定冠词。不要把国籍形容词与国家名混用。</p></details><p><strong>表达迁移：</strong> 围绕“介绍新认识的人和辨认品牌”写两至三句，再读给同伴听。至少使用一次身份介绍与特殊疑问句，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>This is Eva. She is German. What make is your camera?</p><p>第一句用 This is 介绍 Eva；第二句用 She 指代 Eva，German 是国籍形容词，作表语，前面不加 a。 What make 是询问品牌的疑问词组；is 位于主语 your camera 之前。这里 make 是名词，不是“制作”的动词。</p></details><p><a href="/life/english/new-concept/book-1/unit-01/lesson-005">回看本课</a></p><h2 id="lesson-6-·-身份介绍与特殊疑问句" tabindex="-1">Lesson 6 · 身份介绍与特殊疑问句 <a class="header-anchor" href="#lesson-6-·-身份介绍与特殊疑问句" aria-label="Permalink to &quot;Lesson 6 · 身份介绍与特殊疑问句 {#lesson-6-·-身份介绍与特殊疑问句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> What make is your camera?</p><h3 id="练习-1-5" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-5" aria-label="Permalink to &quot;练习 1 {#练习-1-5}&quot;">​</a></h3><p>补全问品牌：What ___ is your camera?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> make</p><p><strong>解析：</strong> 按本课规则判断：介绍某人可以用 This is + 姓名。描述国籍通常用 be + 国籍形容词，不加 a。what make 询问品牌，make 在这里是名词；特殊疑问句常用疑问词组 + be + 主语。单数职业名词一般需要 a/an，品牌专名通常不用不定冠词。不要把国籍形容词与国家名混用。</p></details><p><strong>表达迁移：</strong> 围绕“介绍新认识的人和辨认品牌”写两至三句，再读给同伴听。至少使用一次身份介绍与特殊疑问句，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>What make is your camera? This is Eva. She is German.</p><p>What make 是询问品牌的疑问词组；is 位于主语 your camera 之前。这里 make 是名词，不是“制作”的动词。 第一句用 This is 介绍 Eva；第二句用 She 指代 Eva，German 是国籍形容词，作表语，前面不加 a。</p></details><p><a href="/life/english/new-concept/book-1/unit-01/lesson-006">回看本课</a></p><h2 id="lesson-7-·-a-an-与职业名词" tabindex="-1">Lesson 7 · a/an 与职业名词 <a class="header-anchor" href="#lesson-7-·-a-an-与职业名词" aria-label="Permalink to &quot;Lesson 7 · a/an 与职业名词 {#lesson-7-·-a-an-与职业名词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> My sister is an engineer.</p><h3 id="练习-1-6" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-6" aria-label="Permalink to &quot;练习 1 {#练习-1-6}&quot;">​</a></h3><p>填冠词：My sister is ___ engineer.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> an</p><p><strong>解析：</strong> 按本课规则判断：单数可数职业名词作表语时一般加 a 或 an。选择取决于紧接着的读音，不是字母名称；engineer 前用 an，teacher 前用 a。What is your job? 询问职业，回答可用 I am a/an ...。be 必须与主语一致：I am、you are、he/she is；不能用职业名词直接作谓语。</p></details><p><strong>表达迁移：</strong> 围绕“询问职业并给出完整身份信息”写两至三句，再读给同伴听。至少使用一次a/an 与职业名词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>My sister is an engineer. Are your parents teachers?</p><p>My sister 为第三人称单数主语，后接 is；engineer 的首音是元音音素，因此用 an，而非 a。 Your parents 是复数主语，问句将 are 提前；teachers 为复数职业，不加 a/an。</p></details><p><a href="/life/english/new-concept/book-1/unit-01/lesson-007">回看本课</a></p>',63)])])}const b=s(n,[["render",i]]);export{u as __pageData,b as default};
